    img.addEventListener("wheel", function(e){
      e.preventDefault();
      var rect = img.getBoundingClientRect();
      var offsetX = e.clientX - rect.left;
      var offsetY = e.clientY - rect.top;
      var delta = Math.sign(e.deltaY) * -zoom;
      var newScale = Math.min(Math.max(scale + delta, minZoom), maxZoom);
      originX = offsetX + (originX - offsetX) * (newScale / scale);
      originY = offsetY + (originY - offsetY) * (newScale / scale);
      scale = newScale;
      update();
    });

    img.addEventListener("mousedown", function(e){
      e.preventDefault();
      isDragging = true;
      lastX = e.clientX;
      lastY = e.clientY;
      img.style.cursor = "grabbing";
    });

    document.addEventListener("mousemove", function(e){
      if (!isDragging) return;
      originX += e.clientX - lastX;
      originY += e.clientY - lastY;
      lastX = e.clientX;
      lastY = e.clientY;
      update();
    });

